INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('rec2Awnf1d1cjvRse', 'anglo-school-celra-girona', 'AngloSchool Celrà', 'Aumet 50 bx. local 7​', '972 909 111', 'info@angloschool.cat', 'angloschool.cat', 'Celrà', 'Think English, Speak English.
A AngloSchool creiem que aprendre anglès és molt més que estudiar vocabulari o completar
exercicis.
És escoltar, provar, equivocar-se, tornar-ho a intentar, guanyar confiança i arribar a utilitzar
l’idioma de manera real.
Fa més de 30 anys que acompanyem infants, adolescents i adults en aquest procés, amb una
metodologia pràctica, comunicativa, vivencial i adaptada a cada etapa.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/fJv0pRm3uLAfHY4YO42RBA/nU3-CVdKUV8NTnR-JdEXXCsQ_EuHLlTX_6FBaHgntr-UGF5mFUZ5iOc7YhvZlnWrSCWR_RSoy9x4i1P6MxhIHS5vguFHe3w50_1vY6IjsxJDzMGE-MVQB_5l5D2b-6P0K-sPywL4Z7rsa1xQfvSOjtahDuhPrPDrKPyk0hfvyoY/tby6taa2XMfT8Pw4ZI-KRPgEQ-kNCC-eUdWAPVJ_Wmc', TRUE, '', 'girona')
