INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recA3O8RKLiSnLOpG', 'centre-civic-onyar-girona', 'Centre Cívic Onyar', 'C. Camp de la Plana, 13 ', '972 010 298', 'cconyar@ajgirona.cat', 'www.girona.cat/ccivics', 'Girona - Vila-roja i Font de la Pólvora', 'El Centre Cívic Onyar (1991) és un equipament municipal amb un fort arrelament al sector Est (Vila-roja, Font de la Pólvora, Mas Ramada i Grup Sant Daniel). Està situat en un punt equidistant de tots els barris de la zona, que facilita una participació propera i accessible.

Els seus orígens parteixen de la demanda de l''associacionisme local per obtenir espais de trobada i activitat, i han configurat el seu caràcter dinàmic, amb un important nivell de participació de la població del mateix territori.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/eOn1aLj9xOWwZcc5CwIJ8A/7IyH6EqqIIhxo1khDk2hkz-Gps5uhGuDiq-pY2Y__3fscoH0U6D0S5zzMqxwKxs7rFkY2RYe1av7Y2cMaNjYFo5-fI7oTsr6flc5sFyqRM8FrHOpQkhUN9xWShtjAzD-ID5XqBjmoEgUvr2vSKkGR6CXGlVAnQd3AmY0bOkwYAM/m0sgNWHpliGjsU-REkuv4vL4me32Wk5wf2KRw5cpBg8', FALSE, '', 'girona')
