VALUES ('recB1BWlEtgd7OH1i', 'associacio-juvenil-salsa-jove-girona', 'Associació Juvenil Salsa Jove', ' Carrer de Josep Maria Prat i Roca, 12, 14', '699 008 522', 'esquerradeltersalsajove@gmail.com', 'https://www.salsajove.org/', 'Girona - Domeny i Fontajau', 'Som molt més que una associació sense ànim de lucre. Som un equip apassionat pel lleure, l’educació i la transformació social. Treballem perquè infants, joves i famílies visquin experiències úniques i creixin en valors. Descobreix-nos!', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/k0sEKZGDHl84caBYRFb1DQ/R1tpHNFDR5JAeZZ5pBR94QpP4r1IB-91n8487x2irPLCsL5MnbTsMsDgZl02dqMoqV5hTF3sNli4xzb_W8-6V7hbUiZ1IX2-8dXVGTqVQRl4Sh1wBecE0Eg_t1A1Gwkkw0tqcGz0THDur027uZ0K241DeZBSQ43o43dpOrQW-J24QpdO81Fr19m9qcq6TJCM9sgnm0qrg0Z5j8MXl0UXZg/oyUfEvgQgSo2FkxJs2KX_V4xo9mVJdATG-dOnQR7O5w', TRUE, '', 'girona')
