INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recE4VGi6iGEmFOSD', 'english-girona', 'English Girona', 'Hortes 22, Entresól B2. 17001', '671 940 129', 'secretaria@englishgirona.net', 'www.englishgirona.net', 'Girona - Barri Vell', 'English Girona és una acadèmia especialitzada en l''ensenyament d''idiomes per a infants, adolescents i adults. Oferim classes d''anglès en grup i particulars, preparació d''exàmens oficials de Cambridge (Young Learners, A2 Key, B1 Preliminary, B2 First, C1 Advanced i C2 Proficiency), cursos intensius, reforç escolar i anglès per a empreses.

Treballem amb una metodologia comunicativa i dinàmica, adaptada a cada etapa educativa, amb l''objectiu que els alumnes desenvolupin les seves competències lingüístiques de manera pràctica i efectiva. Som centre preparador oficial d''exàmens Cambridge i comptem amb una àmplia experiència en la preparació de certificacions oficials.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/hY85ioJHGeQjCLTnUq7xBQ/9eLU7yjffUGuYmxKkPLgExwaKHfe9M76NG_Yg949KLEa-tju2DCe7qYY_LWP82hgTccxB3iBl1lwgGNPG49Amj_cxypjIxPqq9Fc8YLBdWb80I6cRQbg5olrUjYh1MkRRZgp4juBsVa-j1R1rOhN3y_D22sHHoQ27_TYBaV-Fzw/sgHVIHeJvkQOPc736YbUmR8NOkGafgMGt19gDFPi7rE', TRUE, '', 'girona')
