INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recEK5NjkjVX97lNl', 'institut-xines-siwei-girona', 'Institut Xinès Siwei', 'Av. Sant Narcís, 14', '695 85 15 06', 'info@institutxines.com', 'https://www.institutxines.com/ca/', 'Girona - Sant Narcís', 'Institut de Llengua i Cultura Xinesa de Girona és un centre educatiu i cultural qualificat com l''escola de xinès a Girona, tenim més de vint anys d’experiències en l´ensenyament del xinès mandarí tant pels catalanes com pels xinesos d’origen xinès . Oferim cursos per a nens de primària, cursos per a estudiants d´ ESO i Batxillerat, i també cursos per a adults. Des de fa sis anys, col·laborem amb les escoles, instituts i acadèmies d´idiomes per a establir els cursos extraescolars i curriculars del xinès mandarí. També organitzem conferencies, seminaris i altres activitats culturals amb
les biblioteques, les escoles i altres institucions culturals a Girona.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/c5eBAJF5saoHTAINQWnObg/P842gAYJtQMOEEJTj4oJafPNzUpA-5SG8VqZSK3MEYsOscoKddBcwM1w_nlXk73ekRM9xysRKfDFyPyh4sFhzOGrzia6En4wtxqrhORuWHM5yAoRR48JMeu0maiCm6_2F-O0lbD_VJs7I0s_OoPIQJelHY_PgyQ6As0vTjWI21c/QUJg1vOTMlmzsCPIQ3gIdlTld5O7OlZxIb3V9XMvYJg', FALSE, '', 'girona')
