INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recEKDGJ8ycpohvWR', 'agro-rural-surf-girona', 'Agro Rural Surf', 'C/ de les Salines, 16, L''Estartit', '660 895 260', 'agroruralsurf@gmail.com', 'https://www.agroruralsurf.com', '', 'A les nostres extraescolars de skate, els infants aprenen els fonaments d’aquest esport, incloent-hi tècniques bàsiques d’equilibri i moviments que els permetran ser més precisos en els trucs. A més, també els ensenyem molts valors de l’skate com el respecte, l’esforç o la perseverança.

Els nostres programes d’extraescolars s’adrecen a alumnes de diferents edats i nivells d’habilitat. Entenem que cada infant és únic, per això treballem per crear una experiència personalitzada que s’adapti als seus objectius individuals.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/KHBBxWfJ84SVWrh8VzN1JQ/bXvxXmxpe2o9n0r8lVV0iRDBEkz7JP6W-R6WfJHjYC6rUnRMQ1NHyyVfHYTJN-ANj4-FkqjxBLPfQWMZBSde6Li6b5VUUZyV6Oeppl410lJSSrlxRGHZkybf84b489IBHNUkhCGSVK7gxRFp89p1yk7t6Jx93dqx7NE8zLtTWD0/8sCWA-9kGnBlYCsQnpYiszQWADAsJiOtoQFPmhANiBA', FALSE, '', 'girona')
