INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recGAl2tXVi7wZkwb', 'associacio-reach-girona', 'Associació Reach', 'Carrer Joan Reglà 10 baixos', '613 23 49 11', 'associacioreach@gmail.com', 'https://associacioreach.org/ca/', 'Girona - Eixample', 'L’Associació Reach té com a missió la sensibilització comunitària per a la prevenció de l’abús sexual infantil.

La sensibilització i la conscienciació dels i les professionals de l’educació que intervenen amb persones menors d’edat.

La sensibilització dels pares i mares que trenqui els mites de què és i com pot passar l’ASI.

La sensibilització dels i les agents socials i professionals vinculats a l’àmbit de la salut i del lleure, per tal d’aconseguir la identificació precoç i efectiva i la derivació als serveis corresponents.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/pn8zQDQJj4U7OVBms30d0A/FgojeeUm_RCnTD9wduUVqnigiOCj8jY_TVry96Hh8VfARbdgvkCCKLYqVA2X4cjbvKgxRydvIgvq5k8rxiFIRV6JjK--nK5MA-wBBdt_ZPVSVGGOJq1f-MswKmcqsXOs1qykT0vkcVlucLoEMRBCdQ/P5D0KrNbIABM5TCUaD_UupxdcZSdzeudIE-Wuyjm1po', TRUE, '', 'girona')
