VALUES ('recGHeFpoHS9TzZPf', 'nipponia-idiomes-girona', 'Nipponia Idiomes', 'Carrer de la Rutlla, 106', '615 14 82 75', 'info@nipponia.cat', 'https://www.nipponia.cat/', 'Girona - Eixample', 'Nipponia va obrir les portes l’any 2005 com el primer centre privat especialitzat en llengües orientals de Catalunya, amb cursos de japonès, xinès i coreà, a més d’anglès, francès i alemany.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/8sVZ_ikTfhxq2xXbyILpSw/hTewnFhTnEdhK1g-w0ALlW9-NOQXgYuKXAMV3iykdxBbO0WgJ-5UTe61mktr23llIs-jS5k4IGOIlA40RbopeFT5znnDUAWfcXsThyeGetGm8nF44jYomU_aUG8mMEzV0gKQ1VMiiDeiwgqHPeNoMJj8l8XVwFJSXdB0JleJg5E/koVz5j2TQr17GSr3p5n3tpiwIer3Y28fnvvq8EGl1ko', TRUE, '', 'girona')
