VALUES ('recHgLj4ryjLawaNz', 'eica-girona', 'Eica', 'C/ Emili Grahit, 73', '97 221 93 39', 'Tlf. 601 37 40 45', 'https://eica.cat/', 'Girona - Eixample', 'Apliquem el nostre mètode d’aprenentatge estructurat i sistematitzat, enfocat en el funcionament del cervell i la pràctica de les 4 habilitats lingüístiques per aconseguir la veritable fluïdesa en el nou idioma.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/3maGFCqtPJ3Jvxt_ec5O3Q/z42iVl7nZ7YBjJqogNHhHGUs7gIBuElfDmqy9vBerrkPz5HnnhY5cwkBrQexQ_tIRsgvlQTYYMyWxG4hDdZxoGhFdWzW8DdOdYFBkThPncLTxnPRHCf-p8HkgA5uLdwepkckAvGTDxqIkyeA759-PgwEOyulBmH7JCnbrqxLvZ8/Mr8xBf91v9TqqR6_32Jr63F0ZJ_xmGmCXsbmBrYsS-g', FALSE, '', 'girona')
