INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recIAWgVhPyjRufJ9', 'girolingua-girona', 'Girolingua', 'C/ Enric-Claudi Girbal i Nadal, 23', '972 22 25 69', 'girolingua@girolingua.cat', 'https://girolingua.cat/', 'Girona - Eixample', 'Girolingua és una acadèmia d’idiomes ubicada al centre de Girona. Fundada l’any 1999 per Núria Farró Negra i Mònica Gou Joher, llicenciades en Filologia Anglo-Germànica per la Universitat Autònoma de Barcelona (UAB), Girolingua és una escola amb una àmplia experiència en l’ensenyament de l’anglès i l’alemany.

L’acadèmia va néixer amb la finalitat d’oferir una alternativa a l’ensenyament tradicional dels idiomes tot incidint en la conversa i en les activitats adequades a cada nivell i tipus d’alumne/a, però sense oblidar altres aspectes de l’educació dels alumnes com l’emotivitat, la creativitat, la responsabilitat i la capacitat de treball, importants en el seu camí cap a la formació com a persones.

Amb aquestes idees inicials i en constant innovació i renovació, Girolingua vol ser una acadèmia diferent, on la familiaritat i el tracte personalitzat amb els alumnes i les famílies siguin la principal base per a un bon aprenentatge dels idiomes.

Tot ho fem amb el convenciment que l’aprenentatge dels idiomes és cada vegada més imprescindible en el món globalitzat en el qual vivim. Amb la mateixa il·lusió dels inicis, amb la mateixa motivació, Girolingua segueix treballant per ser molt més que una escola d’idiomes. Vine a visitar-nos! ', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/QzaGo8WAahherJtEweNSQg/rVB4iggPXP9W68R6Lq92m4Sjz8s2dNvEwiYIMLvwRsZViQRj9RCDrOyFsXXSrQ1m_QycBkJJhUUG1reXFFyZyw_C3sGIVvcp1aKN7qGEoeh5MNsCtSpytyQYHPhnFlKmGjTZJ_ivJbog2_BjMgl2ZX7oUgAaBWwV2U-jcE9dd5KiBsG9TSnc0q3lO3pdIVCh/8FrFdF_s_aVGn-mRpw7gnnRJkIcU2uuhj7P2qEt4JTQ', TRUE, '', 'girona')
