INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recN6Rze1OGCVUile', 'mirades-sils-girona', 'MIRADES', 'Masia Can Serra, Veïnat de la Barceloneta, 15', '676313185', 'info@miradessils.com', 'https://miradessils.com/', 'Sils', 'Mirades és un projecte d’educació lliure i viva ubicat a la Masia Can Serra del Veïnat de la Barceloneta de Sils (La Selva, Girona). Oferim un espai d’acompanyament diari per a famílies, amb infants de 9 mesos (aprox.) fins als 6 anys, que busquen una alternativa a l’escola convencional, on el respecte pels ritmes de l’infant i el contacte directe amb la natura són els pilars fonamentals.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/QDpwD1nBMhjzpCPLjUB-1w/trbTsQNL40n_mZV-ZBmY3B7fVwxAw2XSst9syEINRkt_w2I_SW83ubg2la4onSMkKhAzkjVlhW3unm90y6xfeVAt4WQs5vOcBUknyS5Kcf7CttzCG-7bKhCPTHyHPXNMQCITYRdgqP2ZvLCxKVn9t0VV3lUW0qPmusJ36OekodyIM2yqbWm9Hkg-yfmYhEuI3m_6Cdcaq1fBebayd38aKg/HveZO9OfMK2U_No7jXNF7JuiTpX8An7mID3g3MDDFoo', TRUE, '', 'girona')
