INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recNTyAM5IJg0uoKk', 'centre-civic-pedret-girona', 'Centre Cívic Pedret', 'C. Pedret, 152-156', '972 212 568', 'ccpedret@ajgirona.cat', 'www.girona.cat/ccivics', 'Girona - Pedret', 'El Centre Cívic de Pedret el trobem a l’antic hospital de Sant Llàtzer al carrer Pedret, just davant el riu Ter. És un edifici de pedra antic d’estil Gòtic tardà inclòs en l’Inventari del Patrimoni Arquitectònic de Catalunya, i disposa d’una superfície de 230 m², distribuïda en dues plantes amb una sala gran al primer pis, i dues aules a la planta baixa. ', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/eOn1aLj9xOWwZcc5CwIJ8A/7IyH6EqqIIhxo1khDk2hkz-Gps5uhGuDiq-pY2Y__3fscoH0U6D0S5zzMqxwKxs7rFkY2RYe1av7Y2cMaNjYFo5-fI7oTsr6flc5sFyqRM8FrHOpQkhUN9xWShtjAzD-ID5XqBjmoEgUvr2vSKkGR6CXGlVAnQd3AmY0bOkwYAM/m0sgNWHpliGjsU-REkuv4vL4me32Wk5wf2KRw5cpBg8', FALSE, '', 'girona')
