VALUES ('recOAhITlxeUs1sRA', 'fedac-sant-narcis-girona', 'FEDAC Sant Narcís', 'Carrer Pare Coll, 3', '972 23 31 42', 'coescolars@santnarcis.fedac.cat', 'https://sites.google.com/fedac.cat/coescolarsfedacsantnarcs/activitats', 'Girona - Sant Narcís', 'Escola concertada al barri de Sant Narcís que ofereix activitats coescolars obertes a qualsevol infant de Girona, encara que no estigui matriculat al centre. Les famílies externes paguen 10 € addicionals el primer mes en concepte d''assegurança.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/FsyJ3c-yHjFQWpFGdgLf2g/VeIArfZlCXMNsXQ_msHaeUdw2BlFEbhaKW8bFw_EK-6zINEq1VT72C3n_vwK_1egsrY1d-wFuRvpVMRe0S1kH4jmwrAaPx4mhBQma4ZZnE1md7TGDkGIJ0MHsiiTt-D6jY72MgJ3CavlsHO2LASl-R3hte-xGCjrViXJkc1XNVE/PWTcgYPi9lJMgz7KRbz6k4Eu9fsxHJIqFZ8kwIqqZbE', TRUE, '', 'girona')
