INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recULd44Ln90T6rsz', 'centre-civic-santa-eugenia-girona', 'Centre Cívic Santa Eugènia', 'C. Santa Eugènia, 146', '972 245 111', 'ccsantaeugenia@ajgirona.cat', 'www.girona.cat/ccivics', 'Girona - Santa Eugènia', 'El Centre Cívic Santa Eugènia està situat en una antiga masia del segle XV, coneguda com Can Ninetes. És un centre cívic que presenta una àmplia i diversa programació cultural, on les entitats de la zona tenen una important participació. Destaquen les nits literàries, els espectacles, les exposicions i les tertúlies i debats. El conjunt de cursos de plàstica, cuina, ball, ioga, etc., són també un bon referent per a molts de ciutadans i ciutadanes del barri i de la ciutat.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/eOn1aLj9xOWwZcc5CwIJ8A/7IyH6EqqIIhxo1khDk2hkz-Gps5uhGuDiq-pY2Y__3fscoH0U6D0S5zzMqxwKxs7rFkY2RYe1av7Y2cMaNjYFo5-fI7oTsr6flc5sFyqRM8FrHOpQkhUN9xWShtjAzD-ID5XqBjmoEgUvr2vSKkGR6CXGlVAnQd3AmY0bOkwYAM/m0sgNWHpliGjsU-REkuv4vL4me32Wk5wf2KRw5cpBg8', FALSE, '', 'girona')
