INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recW2bp4m8lOnAUai', 'centre-civic-pont-major-girona', 'Centre Cívic Pont Major', 'C. Pont Major, 67-73', '972 205 244', 'ccpontmajor@ajgirona.cat', 'www.girona.cat/ccivics', 'Girona - Pont Major', 'El Centre Cívic Pont Major (2003) és un equipament municipal adreçat al conjunt de la població, a les associacions del barri i col·lectius diversos. El centre ofereix una programació que s''organitza a través de la participació activa de les entitats i col·lectius del barri. Activitats per a gent gran promogudes per l''Associació de Jubilats La Unió, projectes i cursos dinamitzats pel Col·lectiu de dones La Cata i festivitats populars promogudes per l''associació de veïns i altres associacions de la zona, pretenen ser un clar exemple de dinamització social i cultural del sector.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/eOn1aLj9xOWwZcc5CwIJ8A/7IyH6EqqIIhxo1khDk2hkz-Gps5uhGuDiq-pY2Y__3fscoH0U6D0S5zzMqxwKxs7rFkY2RYe1av7Y2cMaNjYFo5-fI7oTsr6flc5sFyqRM8FrHOpQkhUN9xWShtjAzD-ID5XqBjmoEgUvr2vSKkGR6CXGlVAnQd3AmY0bOkwYAM/m0sgNWHpliGjsU-REkuv4vL4me32Wk5wf2KRw5cpBg8', FALSE, '', 'girona')
