INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recY1lKxx9NKIypox', 'la-diana-girona', 'La Diana', 'Passeig d''Olot, 68, 17006', '644 251 800', 'hola@ladiana.cat', 'https://ladiana.cat/', 'Girona - Santa Eugènia', 'La Diana és una escola d’arts escèniques inspirada en el mètode Stanislavski, que utilitzen altres centres com Actor’s Studio de Nova York.

Amb el nostre mètode, cada alumne farà un treball d’investigació basat en l’assaig, l’autocrítica i en l’avaluació continuada de cada exercici per trobar les eines necessàries per ser actors i actrius professionals, espontanis, creatius, participatius i constructius.

Volem aconseguir que l’alumne experimenti les emocions reals que viu el personatge jugant a creure i viure les situacions de l''”aquí i ara” de l’escena.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/5frHG0SYKXdaj3GAcBTcrg/3OQhHORZMWJh_B-QGk6xlOOkPjU6DQN7hIO4XjQa37oSRksenf-yNmUCf811h2fZKOCG3Czgqj7cbLCnB-wXKSJrJILgJmVcQAqviSnHJN5ojlfYE9JCNJv50Cf8w2JuI-cYRBAD61nwMPOg49vEAA/cjfRuI_665Fo-ZDoY2uO9Ti8FEMlN0Ul0jIGEhwo-ZU', FALSE, '', 'girona')
