INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recdEBB9Q3oWwXw6r', 'codelearn-girona', 'Codelearn Girona', 'Carrer Maluquer Salvador 20, 17002 Girona', '722 664 716', 'girona@codelearn.cat', 'codelearn.cat/girona', 'Girona - Eixample', 'Codelearn és una extraescolar de pensament computacional, programació, robòtica, electrònica i molt més. Hem desenvolupat un mètode que converteix l’aprenentatge de la programació en un joc i anima els alumnes a esdevenir creadors de tecnologia.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/36e0-qOx2QCKfHxBXu_BfA/Sw4Rtl5PLbFJjUIuImbFgmhLFrcTaM8vQ0s9Vfrq4KdXQTU0pqOWrN9nnujDTp58KsFQd7nItOkp-U2aOAnF1AvADwYI2eCmbt44n2Qp9mdecCj34HdjAtJgaKvwDx5U8QDWHi12GD_Zjb0VbhTz288qIlorPAATrD00uQae9pU/oqXihojNs51lw0NzcS1oivt29mW5OTvLmJiv5-dSgNU', TRUE, '', 'girona')
