INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recdoZuN00s0JNyRK', 'tictac-serveis-girona', 'TIC TAC Serveis', 'C/ Pins d''en Ros, 12, 17460 Celrà', '972 494 294', 'info@tictacserveis.com', 'https://www.tictacserveis.com', '', 'Empresa de serveis educatius a Girona. Ofereix extraescolars, casals, monitoratge, idiomes, reforç, mecanografia, ball, costura, ceràmica, ciència i moltes més activitats a diverses escoles de les comarques gironines des de fa més d''una dècada.', '', FALSE, '', 'girona')
