INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recgUj4gR0bF8MiKP', 'diverfut-academy-girona', 'DiverFut Academy', 'Avinguda de Montilivi, 143 Zona esportiva del campus de Montilivi', '601 374 045', 'diverfut.academy@gmail.com', 'https://diverfutgirona.com/', 'Girona - Montilivi-Palau', 'A Diverfut som un projecte educatiu i esportiu que entén el futbol com una eina per al desenvolupament personal i esportiu de nens i joves. Acompanyem cada jugador i jugadora en el seu creixement, fomentant valors com ara el respecte, l''esforç, el treball en equip i la confiança.

Posem la persona al centre, creant un entorn segur, positiu i motivador on puguin gaudir, aprendre i evolucionar al seu ritme. Treballem amb una metodologia adaptada a cada edat i nivell, que combina aprenentatge lúdic, desenvolupament tècnic i motriu, millora tàctica i acompanyament educatiu i emocional.

El nostre objectiu no és només el rendiment esportiu sinó formar persones amb valors, capaços de superar reptes i gaudir del procés d''aprenentatge.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/fs412bRlr-nSsiFWwLe5SQ/rLqKsUXMwJktyIxi8Ir3xqDwJbX6Z23KAiNX_8BCe8geFuIj2cpUSjnd_iT5UT4eaPNPdU2oK0lhLv2BQWhA8NZ1GX4bV--IoQh0K8b8sP6SEadDVcUT_j-OluSqgSqHhy4JkTyXLeYSLEzsrELEI0qVq9GpVc_7JBjPVAZTV4I/WmH4XnE-kROQryzQhAkkjFTyMyFa0E4AE91LzS5N04g', TRUE, '', 'girona')
