VALUES ('recoLWuJYwfIni4h6', 'algorithmics-girona', 'Algorithmics Girona ', 'C/ Rutlla 112-114, 1r pis, 17003', '622 51 87 32', 'girona@algoacademy.es', 'https://es.alg.academy/centro?url=algorithmics-girona', 'Girona - Eixample', 'Escola de programació per a joves de 6 a 18 anys. Ofereix extraescolars de programació, disseny de videojocs i Scratch a diverses escoles de Girona.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/ZTU3iJz1CZ_DpsjxWUZtTw/Oumegg9epVYhTaopAb7IMXuxef43JEeaLfNRkwP9er85mw1nMn7lCKqzWtKVpMO7ne7CdorMYOfotuKUz1RHsACdUhoJut7Tm1XTXfED6h6cPK66g9lNSxK2d0bXpuQSG3LSEKrXqGo8tFlnOSam-1nXvTzqU0AnUIUCGUwyEFY/7hg7HnI_ZhAO4OL1MMAKx_LT7g8rVs9PTyC9edtiL40', TRUE, '', 'girona')
