INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recocKPYDHMx8CNcG', 'el-galliner-girona', 'El Galliner', 'Els Maristes Avinguda del President Josep Tarradellas i Joan, 5, 7, 17007 Girona', '972 205 884', 'elgalliner@elgalliner.cat', 'https://elgalliner.cat/', 'Girona - Santa Eugènia', 'El Galliner és l''escola de teatre i arts escèniques de referència a Girona per a infants i joves. Ubicat a l''Avinguda del President Tarradellas, al barri de Santa Eugènia, el centre porta anys formant nenes i nenes, adolescents i joves en les disciplines del teatre, el circ i el teatre musical, amb una metodologia pròpia que combina el joc, la creativitat i la tècnica escènica.
L''oferta de El Galliner s''organitza per franges d''edat molt ben definides, des dels 4 anys fins als 18, perquè cada grup treballi al seu ritme i amb els reptes adequats. Els Pollets Artístics (4-6 anys) és el punt de partida: un espai de joc dramàtic i expressió lliure per als més petits. Les Gallinetes (7-8 anys), els Pollastres (9-11 anys), els Nuggets (12-14 anys) i els Galls (15-18 anys) conformen l''itinerari de teatre infantil i juvenil. Per als qui volen combinar veu, moviment i actuació, el Teatre Musical Juvenil (12-18 anys) és una de les propostes més completes del centre. I per als qui s''atreveixen amb l''acrobàcia i les arts del circ, el Circ Juvenil (12-18 anys) ofereix una experiència única a Girona.
El Galliner no és una escola convencional: és una comunitat artística on els joves aprenen a pujar a un escenari, a treballar en equip i a confiar en ells mateixos. Els espectacles de final de curs, oberts al públic, són un dels moments més esperats de la temporada per a les famílies de Girona.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/5mAaCvKas3rlQABF7lK5Gg/B6ZMa4tngNYH6oYf4o3DJ4lgcYRr-tPcSmZFZES4gD0xBTtgP18nnl95_f6BRJ4QUYlY6RJNdQ4sI_GQ7i-PVuR9ZWsdOKoJSIJGLoHVXMIulE5mCwUnRufXhjH_hRuExg3VthIMowt8S8DYhpcV7qquankJ72dWoBmKbX6_89vmF80gXSan5oOgzpG9LHhkudAXIJeU2ApB4ieF6yOD8A/oolTgHat8B4ndCX6RQLsWR9mRS8h687qah8XsAcTn0U', TRUE, '', 'girona')
