VALUES ('recs9ZgVEqRpmjJwt', 'la-bullidora-girona', 'La Bullidora', 'Carrer de la Rutlla, 112-114', '692 125 228', 'labullidora@labullidora.com', 'https://labullidora.com/', 'Girona - Eixample', 'La Bullidora és un espai creatiu de la nostra ciutat, Girona on trobareu activitats educatives, creatives i terapèutiques encarades a incentivar la capacitat creadora de les persones.', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/HyEHSohCezbcJupLgV0Dkw/s11y5zWT9_Po-qWQTLn0MfvWUwpDU-XHda37o3zTy-kI_o1l2gfOUPED3uRQvi49N2rkXVb5lEqLbejytdWgDQn0xuGgShgEfLJlY2ySd7hWfBlagqZH3WICIOaJRseN-vpOk30Afrg2QMNIEodI8UNoHvuUwFOQBKVYm7cSdgE/ndbSVUP-xxeMVvis3vFqOMRxlWwZ6xcG83dZK_1fKI0', FALSE, '', 'girona')
